-- State transitions declared for MailPresence (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION messaging.mail_presences_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('away', 'offline'), ('away', 'online'), ('offline', 'away'), ('offline', 'online'), ('online', 'away'), ('online', 'offline'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: mail_presences.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS mail_presences_status_transition_check ON messaging.mail_presences;
CREATE TRIGGER mail_presences_status_transition_check
    BEFORE UPDATE OF "status" ON messaging.mail_presences
    FOR EACH ROW EXECUTE FUNCTION messaging.mail_presences_status_transition_check();
